 const root=shadow.querySelector('#gv-lift-proposal'),q=s=>root.querySelector(s),all=s=>[...root.querySelectorAll(s)],motion=doc.defaultView.matchMedia('(prefers-reduced-motion:reduce)'),oldWidth=dialog.style.getPropertyValue('width'),priority=dialog.style.getPropertyPriority('width');
