 function read(){const p=getProfile();v=approvedLiftView(p,floor,mode);floor=v.floor;local={materials:p.materials,gate:p.descent.gate,bosses:p.descent.bosses,stops:p.descent.stops,best:p.best,seals:p.seals,abyssBest:p.abyssBest||0};current={abyss:v.abyss,biomes:v.biomeCards.map(b=>({...b,image:b.panorama.source})),floors:v.floors.map(f=>({floor:f.actionValue,biome:v.biome,selected:{address:f.address,stars:f.stars,reached:f.reached,boss:f.boss,stopActive:p.descent.stops.includes(f.actionValue)||(f.actionValue-1)%5===0&&f.canStart}}))};for(const k of v.abyss.preparation.skills)DATA.skillIcons[k.id]=imageSource(preparationSkillGlyph(k));}
